body_md:
While logistic damping is known to suppress blow-up in related
chemotaxis systems
(\cite{Lankeit Wang(2017),Osaki(2002),Winkler(2010CPDE),Zhang(2021)}),
its effect in the present degenerate consumption system has remained
elusive; in particular, whether \(L^\infty\)-boundedness holds has been
an open question, to the best of our knowledge. To this end, we
consider the initial-boundary value problem
\begin{equation}\label{1.1}
	\left\{
	\begin{array}{ll}
		u_t=\Delta(\phi(v)u)+au-bu^2, & x\in\Omega,\ t>0,\\[2mm]
		v_t=\Delta v-vu, & x\in\Omega,\ t>0,\\[2mm]
		\partial_\nu u=\partial_\nu v=0, & x\in\partial\Omega,\ t>0,\\[2mm]
		u(\cdot,0)=u_0,\quad v(\cdot,0)=v_0, & x\in\Omega,
	\end{array}
	\right.
\end{equation}
where \(\Omega\subset\mathbb R^2\) is a bounded domain with smooth
boundary.
Here \(a>0\), \(b>0\), and the initial data \((u_0,v_0)\)
satisfy
\begin{equation}\label{1.8}
	\left\{\begin{array}{ll}
		u_0\in W^{1,\infty}(\Omega)\mbox{ is nonnegative with }u_0\not\equiv0,\\[1mm]
		v_0\in W^{1,\infty}(\Omega)\mbox{ with }v_0>0\mbox{ in }\overline{\Omega}.
	\end{array}
	\right.
\end{equation}
The motility function \(\phi\) is assumed to be algebraically
degenerate near zero in the sense that
\begin{equation}\label{1.5}
    \phi\in C^0([0,\infty))\cap C^3((0,\infty))\mbox{ is such that }\phi(0)=0\mbox{ and }\phi>0\mbox{ on }(0,\infty),
\end{equation}
and that for some $\alpha\geq 1$,
\begin{equation}\label{1.6}
	\liminf_{s\searrow0}\frac{\phi(s)}{s^\alpha}>0,\qquad
	\limsup_{s\searrow0}\frac{|\phi'(s)|}{s^{\alpha-1}}<\infty.
\end{equation}
The existence of a  classical solution to \eqref{1.1} was established in \cite{Wang2025}; see Proposition \ref{pro1.1} below.

\label{theorem1.1}
Under assumptions \eqref{1.8}--\eqref{1.6}, any globally classical solution $(u,v)$ of problem \eqref{1.1} satisfies
\begin{equation}
    \|u(\cdot,t)\|_{L^{\infty}(\Omega)}+\|v(\cdot,t)\|_{W^{1,\infty}(\Omega)}\leq C~~\mbox{for all}~~t>0,
\end{equation}
where $C>0$ depends only on the initial data and parameters.

\label{theorem1.2}
Assume that \eqref{1.8}--\eqref{1.6} hold with \(\alpha>1\).
Then there exist constants \(C_v>0\) and \(\lambda>0\) such that
\begin{equation}\label{1.10}
\|v(\cdot,t)\|_{W^{1,\infty}(\Omega)}
\leq C_v e^{-\lambda t}
\qquad\text{for all }t>0.
\end{equation}
Moreover, for every \(1\leq p<\infty\), there exist constants
\(C_p>0\) and \(\eta_p>0\) such that
\begin{equation}\label{1.11a}
\left\|u(\cdot,t)-\frac{a}{b}\right\|_{L^p(\Omega)}
\leq C_p e^{-\eta_p t}
\qquad\text{for all }t>0.
\end{equation}
In particular,
\begin{equation}\label{1.12}
u(\cdot,t)\overset{*}{\rightharpoonup}\frac{a}{b}
\quad\text{in }L^\infty(\Omega)
\quad\text{as }t\to\infty.
\end{equation}

(\cite{WinklerDCDSB})\label{le2.3}
	Let $ q\geq2$, and $\varphi\in C^2(\overline{\Omega})$ be positive  satisfying $\frac{\partial\varphi}{\partial\nu}=0$ on $\partial\Omega$. Then
	\begin{equation*}
		\begin{split}			\int_{\Omega}\varphi^{-q-1}|\nabla\varphi|^{q+2}\leq(q+\sqrt{2})^2
\int_{\Omega}\varphi^{-q+3}|\nabla\varphi|^{q-2}|D^2\ln\varphi|^2
			\end{split}
	\end{equation*}
	and
	\begin{equation*}
		\begin{split}
			\int_{\Omega}\varphi^{-q+1}|\nabla\varphi|^{q-2}|D^2\varphi|^2\leq(q+\sqrt{2}+1)^2\int_{\Omega}\varphi^{-q+3}|\nabla\varphi|^{q-2}|D^2\ln\varphi|^2.
		\end{split}
	\end{equation*}

\label{le2.4}
Let $\Omega\subset\mathbb R^2$ be a bounded domain with smooth boundary, and let $a,b>0$. Under the
assumptions \eqref{1.8}--\eqref{1.6},  the following estimates hold:
		\begin{equation}\label{2.1}
		\int_{\Omega}u(\cdot,t)\leq m:=\max\{\int_{\Omega} u_0,\frac{a|\Omega|}{b}\}~~~~\mbox{for all}~t\in(0,\infty).
	\end{equation}
	\begin{equation}\label{2.5*}
		\int_t^{t+1}\int_{\Omega}u^2\leq\frac{(a+1)m}{b}~~~~\mbox{for all}~t\in(0,\infty).
	\end{equation}
as well as
	\begin{equation} \label{2.2}
		v(x,t)\leq\|v_{0}\|_{L^{\infty}(\Omega)}~~~~\mbox{for all}~(x,t)\in\bar{\Omega}\times [0,\infty).
	\end{equation}

By the H\"{o}lder inequality, integrating the first equation in \eqref{1.1} yields
	\begin{equation*}
		\frac{d}{dt}\int_{\Omega}u= a\int_{\Omega}u-b\int_{\Omega}u^2\leq a\int_{\Omega}u-\frac{b}{|\Omega|}\bigg(\int_{\Omega}u\bigg)^2 \quad\hbox{for all}~t>0,
	\end{equation*}
	which along with an ODE comparison argument clearly implies \eqref{2.1}.
Then \eqref{2.5*} follows by integrating the same identity and applying the Cauchy--Schwarz inequality. Finally, \eqref{2.2} is a direct consequence of the maximum principle applied to the second equation in \eqref{1.1}, since $uv\ge0$.

\label{le2.5} Let $\Omega \subset \mathbb R^2$ be  a smoothly bounded domain. Then for all $p\geq1$ and
	\begin{equation*}
		\begin{aligned}
			\theta\in\left\{
			\begin{array}{l}
				{\left({1,\frac{2p}{2-p}}\right)},\quad p< 2, \\
				{(1,\infty)},\quad\quad p=2,\\
				{(1,\infty]},\quad\quad p>2,
			\end{array}\right.
		\end{aligned}
	\end{equation*}
	there exists a constant $C>0$ such that
	\begin{equation}
		\|v(\cdot,t)\|_{W^{1,\theta}(\Omega)}\leq C(1+\sup\limits_{s>0}\|u(\cdot,s)\|_{L^p(\Omega)})~~\mbox{for all} ~t\in(0,\infty).
	\end{equation}

\label{lemma3.3}
	Let $\Omega\subset\mathbb{R}^2$ be a smoothly bounded domain and $q\geq 2$. Then there exists $C(q)>0$ such that for all $t\in(0,\infty)$,
	\begin{equation}\label{3.1**}
		\begin{split}
			&\frac{d}{dt}\int_{\Omega}\frac{|\nabla v|^q}{v^{q-1}}+\frac{q}{8(q+\sqrt{2})^2}\int_{\Omega}\frac{|\nabla v|^{q+2}}{v^{q+1}}+(q-1)^2\int_\Omega u\frac{|\nabla v|^q}{v^{q-1}}
			\leq  C(q)\bigg\{\int_{\Omega}u^{\frac{q+2}{2}}v+\int_\Omega v\bigg\}.
		\end{split}
	\end{equation}

\label{L2bound}
    Let $\Omega\subset\mathbb{R}^2$ be a smoothly bounded domain, $a>0$ and $b>0$.
    Suppose that \eqref{1.5}--\eqref{1.6} hold with $\alpha\ge1$, and that \eqref{1.8} is valid.
    Then there exists a constant $C>0$ such that
    \begin{equation}\label{3.8}
        \|u(\cdot,t)\|_{L^2(\Omega)} \le C \quad \text{for all } t>0.
    \end{equation}

Applying Lemma \ref{lemma3.3} to $q:=2$, we can find some $c_1>0$ and $c_2>0$ such that
	\begin{align}\label{3.9*}
		\frac{d}{dt}\int_\Omega \frac{|\nabla v|^2}{v}+\frac{1}{128}\int_\Omega \frac{|\nabla v|^{4}}{v^3}+\int_\Omega u\frac{|\nabla v|^2}{v}\leq c_1\bigg\{\int_{\Omega}u^{2}+\int_\Omega v\bigg\}
	\end{align}
and
    \begin{equation}\label{3.11**}
        \frac{d}{dt}\int_\Omega \frac{|\nabla v|^2}{v}+\int_\Omega\frac{|\nabla v|^2}{v}\leq c_2\bigg\{\int_{\Omega}u^{2}+\int_\Omega v\bigg\},
    \end{equation}
    where the latter follows from the elementary inequality
    $\int_\Omega\frac{|\nabla v|^2}{v}\leq\frac{1}{128}\int_{\Omega}\frac{|\nabla v|^4}{v^3}+32\int_{\Omega}v.$

 In view of \eqref{2.5*},  \eqref{3.11**} implies that $\int_{\Omega}\frac{|\nabla v|^2}{v}(\cdot,t)\leq c_3$ for some $c_3>0$  and all $t>0$.
 Integrating \eqref{3.9*} over the interval $(t,t+1)$ then gives
	$$\int_t^{t+1}\int_{\Omega}\frac{|\nabla v|^4}{v^3}
	\leq c_4~~\mbox{for all}~~t>0.$$

Next, testing the first equation in
 \eqref{1.1} by $u$ and applying Young's inequality, along with the assumptions  \eqref{1.6}, we can find $c_5>0$ and $c_6>0$ such that
	\begin{align}\label{3.11}
		\frac{d}{dt}\int_{\Omega}u^2+ c_5\int_{\Omega} v^\alpha|\nabla u|^2+2b\int_{\Omega} u^3\leq c_6\int_{\Omega} u^2v^{\alpha-2}|\nabla v|^2+2a\int_{\Omega} u^2.
	\end{align}

    By Young's inequality,  the first term on the right-side of \eqref{3.11}   can be estimated as
    \begin{equation}\label{3.12}
	c_6\int_{\Omega} u^2v^{\alpha-2}|\nabla v|^2\leq c_5\int_\Omega v^\alpha|\nabla u|^2+c_7\bigg\{\int_{\Omega}u^2+1\bigg\}\bigg\{\int_{\Omega}\frac{|\nabla v|^4}{v^3}+1\bigg\}
\end{equation}
        with some $c_7>0$; for a detailed derivation of this estimate, we refer to \cite[Lemma 3.7]{Wang2025}.

Therefore, inserting \eqref{3.12} into \eqref{3.11} leads to
	\begin{align*}
			\frac{d}{dt}\int_{\Omega}u^2+2b\int_{\Omega} u^3                                                                                                                                                       
\leq (2a+c_7) \bigg\{\int_{\Omega}u^2+1\bigg\}\bigg\{\int_{\Omega}\frac{|\nabla v|^4}{v^3}+1\bigg\}.
	\end{align*}
Since, by Young's inequality,
\begin{align*}
	b|\Omega|^{-\frac{1}{2}}\bigg\{\int_{\Omega}u^2 +1\bigg\}^{\frac{3}{2}}\leq \sqrt{2}b|\Omega|^{-\frac{1}{2}}\bigg\{\int_{\Omega}u^2\bigg\}^{\frac{3}{2}}
+\sqrt{2}b|\Omega|^{-\frac{1}{2}}\leq2b\int_{\Omega}u^3+2b|\Omega|^{-\frac{1}{2}},
\end{align*}
it follows that
	\begin{align}\label{3.13**}
	\frac{d}{dt}\int_{\Omega}u^2+	b|\Omega|^{-\frac{1}{2}}\bigg\{\int_{\Omega}u^2 +1\bigg\}^{\frac{3}{2}}\leq c_{8}\bigg\{\int_{\Omega}u^2 +1\bigg\}
\bigg\{\int_{\Omega}\frac{|\nabla v|^4}{v^3}+1\bigg\}
\end{align}
where $c_8=2a+c_7+ 2b|\Omega|^{-\frac{1}{2}}$ for all $t>0$.
Writing $y(t):=\int_{\Omega}u^2+1$ and $g(t):=c_{8}\int_{\Omega}\frac{|\nabla v|^4}{v^3}+c_{8}$, \eqref{3.13**} shows
\begin{align*}
	y'(t)+b|\Omega|^{-\frac{1}{2}}y^{\frac{3}{2}}(t)\leq y(t)g(t)
\end{align*}
for all $t>0$, which, by a standard ODE comparison argument, yields \eqref{3.8} with the desired constant $C>0$.

From the version of the Gagliardo--Nirenberg inequality (\cite{Winkler(2010)}),   it follows that for $1<r<\infty$ there exists $c_1=c_1(r,\Omega)>0$ such that
		\begin{align}\label{3.1*}
			\|\varphi^{\frac{p}{2}}\psi^{\frac{\alpha}{2}}\|^2_{L^{r}(\Omega)}&\leq c_1\|\nabla
			(\varphi^{\frac{p}{2}}\psi^{\frac{\alpha}{2}})\|^{2\theta}_{L^{2}(\Omega)}
\|\varphi^{\frac{p}{2}}\psi^{\frac{\alpha}{2}}\|^{2(1-\theta)}_{L^{\frac{2}{p}}(\Omega)}
			+c_1\|\varphi^{\frac{p}{2}}\psi^{\frac{\alpha}{2}}\|_{L^{\frac{2}{p}}(\Omega)}^2,
		\end{align}
		with $\theta:=1-\frac{2}{rp}$.
		For any $\eta_1>0$,
		the Young inequality leads to
		\begin{align*}
			c_1\|\nabla
			(\varphi^{\frac{p}{2}}\psi^{\frac{\alpha}{2}})\|^{2\theta}_{L^{2}(\Omega)}
			\|\varphi^{\frac{p}{2}}\psi^{\frac{\alpha}{2}}\|^{2(1-\theta)}_{L^{\frac{2}{p}}(\Omega)}
			&\leq \eta_1 \|\nabla (\varphi^{\frac{p}{2}}\psi^{\frac{\alpha}{2}})\|_{L^{2}(\Omega)}^2
			+c_2(\eta_1,\theta)\|\varphi^{\frac{p}{2}}\psi^{\frac{\alpha}{2}}\|_{L^{\frac{2}{p}}(\Omega)}^2,
		\end{align*}
		where $c_2(\eta_1,\theta)={\eta_1}^{\frac{\theta}{\theta-1}} {c_1}^{\frac{1}{1-\theta}}.
		$

		At this position,  an application  of the H\"{o}lder inequality yields
		\begin{equation}\label{3.2d}
			\begin{split}
				\|\varphi^{\frac{p}{2}}\psi^{\frac{\alpha}{2}}\|_{L^{\frac2{p}}(\Omega)}^2
&=\bigg\{\int_\Omega\varphi\psi^{\frac{\alpha}{p}}\bigg\}^{p}	\leq\bigg\{\sup\limits_{x\in\Omega}|\psi(x)|\bigg\}^{\alpha}\cdot\bigg\{\int_\Omega\varphi\bigg\}^{p}.
			\end{split}
		\end{equation}
		In addition, a simple calculation shows that
		\begin{align}\label{3.2e}
			\eta_1\|\nabla
			(\varphi^{\frac{p}{2}}\psi^{\frac{\alpha}{2}})\|_{L^{2}(\Omega)}^2
			&=\eta_1\int_\Omega\bigg|\frac{p}{2}\varphi^{\frac{p-2}{2}}\psi^{\frac{\alpha} 2}\nabla\varphi+\frac{\alpha}2 \varphi^{\frac{p}{2}}\psi^{\frac{\alpha-2} 2}\nabla\psi\bigg|^2\nonumber\\
			&\leq \eta_1p^2\int_\Omega\varphi^{p-2}\psi^{\alpha}|\nabla\varphi|^2
			+\eta_1\alpha^2 \int_\Omega\varphi^{p}\psi^{\alpha-2}|\nabla\psi|^2\nonumber\\
			&\leq\eta\int_\Omega\varphi^{p-2}\psi^{\alpha}|\nabla\varphi|^2
			+\eta\int_\Omega\varphi^{p}\psi^{\alpha-2}|\nabla\psi|^2
		\end{align}
		by the choice of	$
		\eta_1:=\min\{\frac{\eta}{p^2},\frac{\eta}{\alpha^2}\}$. From \eqref{3.1*}--\eqref{3.2e}, it follows that \eqref{3.1} holds with the desired $C(\eta,p,r,\alpha,\Omega)>0$.

\label{le3.2}
	Let $\Omega\subset\mathbb{R}^2$ be a smoothly bounded domain, $L>0$, $p_0\geq1$, $p>2$, $q>2+\frac{2p}{p_0}$, $\alpha\geq1$ and $\beta\in [1,p+p_0)$. Then for any $\eta\in(0,1)$, there exists $C=C(\eta,L,p,\beta,p_0,q,\alpha,\Omega
	)>0$ such that for all  $\varphi\in C^1(\overline \Omega)$ and $\psi \in C^1(\overline \Omega)$ fulfilling $\varphi> 0$, $\psi>0$ in $\overline \Omega$ and $\int_{\Omega}\varphi^{p_0}\leq L$, we have
	\begin{align*}
		\int_{\Omega}\varphi^{\beta} \psi^{\alpha}&\leq \eta \int_{\Omega}\varphi^{p-2}\psi^{\alpha}|\nabla
		\varphi|^2+\eta \int_{\Omega}\varphi{\psi}^{-q+1}|\nabla  \psi|^q+C\left\{\sup\limits_{x\in\Omega}\psi(x)+1\right\}^\tau\left\{\int_{\Omega}\varphi+\left(\int_{\Omega}\varphi\right)^{p}\right\}
	\end{align*}
	with $\tau:=\frac{pq(\alpha-1)}{q-2}+1$.

\label{le3.6}
	Let $\Omega\subset\mathbb{R}^2$ be a smoothly bounded domain, $\alpha\geq1$.  Then for any $p>2$ and $p+2<q<2p$, one can find a constant $C=C(p,q)$ such that 	for all $t>0$
	\begin{equation}\label{3.17}
			\int_\Omega u^p+\int_\Omega v^{-q+1}|\nabla v|^q\leq C.
	\end{equation}

From \eqref{2.2} and \eqref{1.6}, it follows that
	there exist positive constants $c_1$ and $c_2$ such that
	\begin{equation}\label{3.17*}
		c_1 v^{\alpha}(x,t)\leq\phi(v(x,t))~~\mbox{and}~|\phi'(v(x,t))|\leq c_2 v^{\alpha-1}(x,t)~~\mbox{for}~(x,t)\in\Omega\times(0,\infty).
	\end{equation}
	Testing the first equation in \eqref{1.1} with $u^{p-1}$ and applying Young's inequality yield
\begin{align}\label{3.16} \frac{1}{p}\frac{d}{dt}\int_{\Omega}u^p&=\int_{\Omega}\Delta(\phi(v) u)u^{p-1}+a\int_{\Omega}u^p-b\int_{\Omega}u^{p+1}\\
		&=-(p-1)\int_{\Omega}\phi(v)u^{p-2}|\nabla u|^2-(p-1)\int_{\Omega}\phi'(v)u^{p-1}\nabla v\cdot\nabla u+a\int_{\Omega}u^p-b\int_{\Omega}u^{p+1}\nonumber\\
		&\leq-\frac{c_1(p-1)}{2}\int_{\Omega}v^\alpha u^{p-2}|\nabla u|^2+\frac{(p-1)c_2^2}{2c_1}\int_{\Omega}u^p v^{\alpha-2}|\nabla v|^2+a\int_{\Omega}u^p-b\int_{\Omega}u^{p+1}\nonumber
\end{align}
for all $t>0$.

 Taking an evident linear combination of  \eqref{3.16} and \eqref{3.1**} with $q\in[2,2p)$ entails that
	\begin{align}\label{3.18}
			\frac{d}{dt}&\bigg(\int_{\Omega}u^p+\int_{\Omega}v^{-q+1}|\nabla v|^{q}\bigg)+\int_{\Omega}u^p+\int_{\Omega}v^{-q+1}|\nabla v|^{q}+\frac{q}{8(q+\sqrt{2})^2}\int_{\Omega}v^{-q-1}|\nabla v|^{q+2}\nonumber\\
			&\quad+\frac{c_1p(p-1)}{2}\int_{\Omega}u^{p-2}v^\alpha |\nabla u|^2+(q-1)^2\int_\Omega u v^{-q+1}|\nabla v|^q\nonumber\\
			&\leq
			\frac{p(p-1)c_2^2}{2c_1}\int_{\Omega}u^p v^{\alpha-2}|\nabla v|^2+\int_{\Omega}v^{-q+1}|\nabla v|^{q}+(ap+1)\int_{\Omega}u^p-bp\int_{\Omega}u^{p+1}\\
			&\quad  +c_3(q)\bigg(\int_{\Omega}u^{\frac{q+2}{2}}v+\int_\Omega v\bigg)\nonumber\\
				&\leq
			\frac{p(p-1)c_2^2}{2c_1}\int_{\Omega}u^p v^{\alpha-2}|\nabla v|^2+\int_{\Omega}v^{-q+1}|\nabla v|^{q}+c_4\bigg(\int_{\Omega}u+\int_{\Omega}v\bigg)-\frac{3bp}{4}\int_{\Omega}u^{p+1}+c_5\int_{\Omega}u^{\frac{q+2}{2}}\nonumber\\
			&\leq
			\frac{p(p-1)c_2^2}{2c_1}\int_{\Omega}u^p v^{\alpha-2}|\nabla v|^2+\int_{\Omega}v^{-q+1}|\nabla v|^{q}-\frac{bp}{2}\int_{\Omega}u^{p+1}+c_6\bigg(\int_{\Omega}u+\int_{\Omega}v\bigg),\nonumber
	\end{align}
	for some $c_i>0~(i=3,4,5,6)$.
We invoke Young's inequality to see that
\begin{equation}
	\begin{split}
		\int_{\Omega}v^{-q+1}|\nabla v|^{q}&=\int_{\Omega}\bigg\{\frac{q}{16(q+\sqrt{2})^2}v^{-q-1}|\nabla v|^{q+2}\bigg\}^{\frac{q}{q+2}}\cdot\bigg\{\big(\frac{16(q+\sqrt{2})^2}{q}\big)^{\frac{q}{q+2}}v^{\frac{2}{q+2}}\bigg\}\\
		&\leq\frac{q}{16(q+\sqrt{2})^2}\int_{\Omega}v^{-q-1}|\nabla v|^{q+2}+c_7(q)\int_{\Omega} v
	\end{split}
\end{equation}
and
\begin{align}\label{3.19}
		&\quad\frac{p(p-1)c_2^2}{2c_1}\int_{\Omega}u^p v^{\alpha-2}|\nabla v|^2\nonumber\\
		&\leq\frac{q}{16(q+\sqrt{2})^2}\int_{\Omega}v^{-q-1}|\nabla v|^{q+2}+c_8(p,q)\int_\Omega u^{\frac{p(q+2)}{q}}v^{\frac{\alpha(q+2)-2}{q}}\\
		&\leq\frac{q}{16(q+\sqrt{2})^2}\int_{\Omega}v^{-q-1}|\nabla v|^{q+2}+c_8(p,q)\|v_0\|_{L^{\infty}(\Omega)}^{\frac{2(\alpha-1)}{q}}\int_\Omega u^{\frac{p(q+2)}{q}}v^\alpha.\nonumber

\end{align}
It is observed that for any fixed $p>2$, one can find $q>1$ such that
	\begin{equation*}
		q\in(p+2,2p)~~\mbox{and}~~
		\frac{p(q+2)}{q}<p+2.
	\end{equation*}
Hence, thanks to \eqref{3.8}, the application of Lemma \ref{le3.2} to $\beta:=	\frac{p(q+2)}{q}$ and $p_0:=2$ yields
	\begin{align}\label{3.23}
		c_8(p,q)\|v_0\|_{L^{\infty}(\Omega)}^{\frac{2(\alpha-1)}{q}}\int_\Omega u^{\frac{p(q+2)}{q}}v^\alpha
		&\leq c_9(p,q)\int_\Omega u^{\frac{p(q+2)}{q}}v^\alpha\nonumber\\
		&\leq\frac{c_1p(p-1)}{4} \int_{\Omega}u^{p-2}v^\alpha|\nabla
		u|^2+\frac{(q-1)^2}{2} \int_{\Omega}u{v}^{-q+1}|\nabla v|^q\\
		&\quad+c_{10}\left\{\sup\limits_{x\in\Omega}v(x)+1\right\}^{\frac{ pq(\alpha-1)}{q-2}+1}\left\{\int_{\Omega}u+\left(\int_{\Omega}u\right)^{p}\right\}.\nonumber
	\end{align}
		From \eqref{3.18}-\eqref{3.23}, it follows that there exists $c_{11}>0$ such that
		\begin{align*}
			&~~\frac{d}{dt}\bigg(\int_{\Omega}u^p+\int_{\Omega}v^{-q+1}|\nabla v|^{q}\bigg)+\int_{\Omega}u^p+\int_{\Omega}v^{-q+1}|\nabla v|^{q}\nonumber\\
			&\quad+\frac{c_1p(p-1)}{4}\int_{\Omega}u^{p-2}v^\alpha |\nabla u|^2+\frac{(q-1)^2}{2}\int_\Omega u v^{-q+1}|\nabla v|^q+\frac{bp}{2}\int_{\Omega}u^{p+1}\\
			&\leq c_{10}\left\{\sup\limits_{x\in\Omega}v(x)+1\right\}^{\frac{\alpha pq}{q-2}+1}\left\{\int_{\Omega}u+\left(\int_{\Omega}u\right)^{p}\right\}+c_{11}\bigg(\int_{\Omega} v+\int_{\Omega} u\bigg).
\nonumber
		\end{align*}
Therefore, due to \eqref{2.1} and \eqref{2.2}, there exists some constant $c_{12}>0$ satisfying
		\begin{equation}\label{3.26*}
			\frac{d}{dt}\mathcal{F}(t)+\mathcal{F}(t)\leq c_{12},
		\end{equation}
	which, via an ordinary differential inequality argument, implies the uniform boundedness of $\mathcal{F}(t)$ and thus leads to \eqref{3.17} readily.

According to the second equation of \eqref{1.1}, we can see that for all $t>0$
	\begin{equation}\label{4.1*}
		\partial_t v^r = \Delta v^r + h(x,t),
	\end{equation}
	where
	$
	h(x,t):= r(1-r) v^{r-2}|\nabla v|^2 - ruv^r.
	$
By the variation-of-constants formula, we have
	\begin{equation}\label{4.1a}
	v^r(\cdot,t)=e^{t\Delta}v_0^r+\int_0^t e^{(t-s)\Delta}h(\cdot,s)\,ds\quad\;for\; all\; t>0.
	\end{equation}

Due to the fact that $r<1$, for any $\theta\ge2$,
	\begin{equation}\label{4.2*}
		\int_\Omega |h|^{\theta}
		\leq 2^\theta\int_\Omega v^{(r-2)\theta}|\nabla v|^{2\theta}+2^{\theta}\int_\Omega u^\theta v^{r\theta}.
	\end{equation}
	Now fix $k > \max\{4,\frac{2}{r}\}$ and choose $\theta\in (2,\frac{k}{2})$. Since $k>4$, we can choose some $p>2$ such that $p+2<k< 2p$. Therefore, Lemma \ref{le3.6} applies with this choice of $p$ and $q=k$, yielding  $$\int_\Omega \frac{|\nabla v|^k}{v^{k-1}}\leq c_1.$$ By H\"older's inequality and \eqref{2.2}, there exist constants $c_2,c_3>0$ such that for all $t>0$,

\begin{align}\label{4.4*}
	 2^{\theta}\int_{\Omega} v^{(r-2)\theta}|\nabla v|^{2\theta}
		&= 2^{\theta}\int_{\Omega}\left\{\frac{|\nabla v|^k}{v^{k-1}}\right\}^{\frac{2\theta}{k}}\cdot v^{\frac{2(k-1)\theta}{k}+(r-2)\theta}\nonumber\\
		&\leq 2^{\theta}\left(\int_{\Omega}\frac{|\nabla v|^k}{v^{k-1}}\right)^{\frac{2\theta}{k}}\cdot\left(\int_{\Omega} v^{\left[\frac{2(k-1)\theta}{k}+(r-2)\theta\right]\cdot\frac{k}{k-2\theta}}\right)^{\frac{k-2\theta}{k}}\\
		&\leq 2^{\theta}|\Omega|^{\frac{k-2\theta}{k}}\|v_0\|_{L^{\infty}(\Omega)}^{\frac{2(k-1)\theta}{k}+(r-2)\theta}\left(\int_{\Omega}\frac{|\nabla v|^k}{v^{k-1}}\right)^{\frac{2\theta}{k}}\nonumber\\
		&\leq c_2,\nonumber
		\end{align}
	and
\begin{equation}\label{4.5*}
		2^{\theta}\int_\Omega u^{\theta}v^{r\theta}\leq 2^{\theta}\|v_0\|_{L^\infty(\Omega)}^{r\theta}\int_\Omega u^{\theta}\leq c_3,
	\end{equation}
	where $\frac{2(k-1)\theta}{k}+(r-2)\theta= \theta(r-\frac{2}{k})>0$.

Applying the smoothing estimates for the Neumann heat semigroup from \cite{Winkler(2010)} to \eqref{4.1a} and \eqref{1.8}, we obtain constants $c_4,c_5>0$ such that for all $t>0$,
\begin{align}
		\|\nabla v^r(\cdot,t)\|_{L^{\infty}(\Omega)}
		&= \left\| \nabla e^{t\Delta}  v_0^r + \int_0^t \nabla e^{(t-s)\Delta} h(\cdot,s)\,ds \right\|_{L^{\infty}(\Omega)} \nonumber\\
		&\leq c_4 \|\nabla  v_0^r
\|_{L^{\infty}(\Omega)} + c_4 \int_0^t (1+(t-s)^{-\frac{1}{2}-\frac{1}{\theta}}) e^{-\lambda(t-s)} \|h(\cdot,s)\|_{L^{\theta}(\Omega)}\,ds \\
		&\leq c_4 \|\nabla  v_0^r
\|_{L^{\infty}(\Omega)}
 + c_4 (c_2+c_3)^{\frac 1 {\theta} } \int_0^t (1+(t-s)^{-\frac{1}{2}-\frac{1}{\theta}}) e^{-\lambda(t-s)}\,ds \nonumber\\
		&\leq c_5,\nonumber
	\end{align}
	due to $\int_0^{\infty} \sigma^{-\frac{1}{2}-\frac{1}{\theta}} e^{-\lambda\sigma}d \sigma<\infty$ and $\|\nabla v_0^r\|_{L^\infty(\Omega)}<\infty$.
Thus $\|\nabla v^r(\cdot,t)\|_{L^\infty(\Omega)}\le c_5$ for all $t>0$, which yields
	$$
	|\nabla v(x,t)| = r^{-1} v^{1-r}(x,t)|\nabla v^r(x,t)|
	\le \frac{c_5}{r} v^{1-r}(x,t).
	$$
	This completes the proof.

\label{lemma3.9}
	Let $\tau\geq1,\rho\geq1,q\geq0$ and $\{N_k\}_{k\in\{1,2,3,...\}}\subset[1,\infty)$ be such that
	\begin{equation*}
		N_{k}\leq \rho^k N_{k-1}^{2+q\cdot 2^{-k}}+\rho^k \cdot\tau^{2^k}~~~~\mbox{for all}~k\geq1.
	\end{equation*}
	Then
	\begin{equation*}
		\liminf\limits_{k\to\infty}N_k^{\frac{1}{2^k}}\leq(2\sqrt{2}\rho^3\tau^{1+\frac{q}{2}}N_0)^{e^{\frac{q}{2}}}.
	\end{equation*}

\label{le3.8Moser}
	Let $\Omega\subset\mathbb{R}^2$ be a smoothly bounded domain.  Then there exists a constant $C>0$ such that for all $t>0$,
	\begin{equation*}
		\|u(\cdot,t)\|_{L^\infty(\Omega)}\leq C.
	\end{equation*}

For arbitrary $T>0$, set $p_k:=2^k$ for $k\geq0$, and define	                                                                           
	\begin{equation}\label{3.36}
	N_k(T):=\sup\limits_{0<t\leq T}\int_\Omega u^{p_k}(\cdot,t)+1,\qquad k\in\{0,1,2,\cdots\}.
\end{equation}


By Proposition \ref{pro1.1}, the solution is classical on $[0,T]$, whence $N_k(T)<\infty$ for each fixed $k$ and $T$. Moreover, according to Lemma \ref{le2.4}, $N_0(T)\le m+1$ with $m$ independent of $T$.

We shall derive a $T$-independent recursive inequality for $N_k(T)$  for $k\geq1$; the desired  uniform bound
will then follow by letting $T\to\infty$.
To this end, we recall from \eqref{1.6} and \eqref{2.2} that
\begin{equation*}
	c_1 v^{\alpha}(x,t)\leq\phi(v(x,t))~~\mbox{and}~~|\phi'(v(x,t))|\leq c_2 v^{\alpha-1}(x,t)~~\mbox{for}~(x,t)\in\Omega\times(0,\infty)
\end{equation*}
for some constants $c_1>0$ and $c_2>0$.

Testing the first equation in \eqref{1.1} with $p_k u^{p_k-1}$, we  arrive at
	\begin{align*}
		\frac{d}{dt}\int_{\Omega}u^{p_k}+b\int_{\Omega}u^{p_k}
		&=p_k\int_{\Omega}\Delta(\phi(v) u)u^{p_k-1}+(ap_k+b)\int_{\Omega}u^{p_k}-bp_k\int_{\Omega}u^{p_k+1}\nonumber\\
		&\leq-c_1p_k(p_k-1)\int_{\Omega}u^{p_k-2}v^\alpha|\nabla u|^2
		+c_2 p_k(p_k-1)\int_{\Omega}v^{\alpha-1}u^{p_k-1}|\nabla v||\nabla u|\nonumber\\
		&\quad+p_k(a+b)\int_{\Omega}u^{p_k}-bp_k\int_{\Omega}u^{p_k+1}\\
		&\leq-\frac{c_1p_k(p_k-1)}{2}\int_{\Omega}u^{p_k-2}v^\alpha|\nabla u|^2+\frac{p_k(p_k-1)c_2^2}{2c_1}\int_{\Omega}v^{\alpha-2}u^{p_k}|\nabla v|^2\\
		&\quad+p_k(a+b)\int_{\Omega}u^{p_k}-bp_k\int_{\Omega}u^{p_k+1}.\nonumber
	\end{align*}
Thanks to Lemma \ref{lem3.5}, there exists $c_r>0$ such that we have
	\begin{align}			&\frac{d}{dt}\int_{\Omega}u^{p_k}+b\int_{\Omega}u^{p_k}+\frac{c_1}{4}\int_\Omega\big|\nabla(u^{\frac{p_k}{2}}
v^{\frac{\alpha}{2}})\big|^2\\
		\leq&\big(\frac{p_k(p_k-1)c_2^2}{2c_1}+\frac{c_1\alpha^2}{4}\big)\int_{\Omega}u^{p_k}v^{\alpha-2}|\nabla v|^2
		+p_k(a+b)\int_{\Omega}u^{p_k}-bp_k\int_{\Omega}u^{p_k+1}\nonumber\\
		\leq&c_{\tau}\big(\frac{p_k(p_k-1)c_2^2}{2c_1}+\frac{c_1\alpha^2}{4}\big)\int_{\Omega}u^{p_k}v^{\alpha-2r}
		+p_k(a+b)\int_{\Omega}u^{p_k}-bp_k\int_{\Omega}u^{p_k+1}\nonumber
		\end{align}
			for all $r\in(0,1)$.
	Since $p_k(p_k-1)\leq p_k^2$ and $\frac{p_k(p_k-1)}{2}\geq\frac{p_k^2}{4}$,  there exists a constant $c_3>0$ independent of $k$ and $T$ such that
	\begin{equation}\label{3.37}
		\begin{split}
			&\frac{d}{dt}\int_\Omega u^{p_k}+b\int_\Omega u^{p_k}+\frac{c_1}{4}\int_\Omega\big|\nabla(u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}})\big|^2\\
\leq &c_3p_k^2\int_{\Omega}u^{p_k}v^{\alpha-2r}+p_k(a+b)\int_\Omega u^{p_k}-bp_k\int_{\Omega}u^{p_k+1}.
		\end{split}
	\end{equation}
 By H\"{o}lder's inequality and the choice $0<r<\min\{1,\frac{\alpha}{4}\}$, we have
	\begin{align}\label{4.10*}
		\int_{\Omega} u^{p_k} v^{\alpha-2r}
		&= \int_{\Omega} \left(u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}}\right)^{\frac{2(\alpha-2r)}{\alpha}} \cdot u^{\frac{2r p_k}{\alpha}}\nonumber \\
		&\leq \left(\int_{\Omega} \left(u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}}\right)^{\frac{2(\alpha-2r)}{\alpha-4r}}\right)^{\frac{\alpha-4r}{\alpha}} \cdot \left(\int_{\Omega} u^{\frac{p_k}{2}}\right)^{\frac{4r}{\alpha}} \\
		&\leq N_{k-1}^{\frac{4r}{\alpha}}(T) \cdot \left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^{\frac{2(\alpha-2r)}{\alpha-4r}}(\Omega)}^{\frac{2(\alpha-2r)}{\alpha}},\nonumber
	\end{align}
where, by the definition of $N_k(T)$ in \eqref{3.36},
	\begin{equation*}
		\begin{split}
			\int_\Omega u^{\frac{p_k}{2}}=\int_\Omega u^{p_{k-1}}\leq N_{k-1}(T).
		\end{split}
	\end{equation*}
 Here, the condition $\alpha\geq1>4r$ allows us to invoke the Gagliardo-Nirenberg inequality, which guarantees the existence of a constant $c_4>0$ independent of $k$ and $T$ such that
 \begin{equation}
 	\begin{split}
 \left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^{\frac{2(\alpha-2r)}{\alpha-4r}}(\Omega)}^{\frac{2(\alpha-2r)}{\alpha}}
 \leq c_4 \left\| \nabla\left(u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}}\right) \right\|_{L^2(\Omega)} \cdot \left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^1(\Omega)}^{\frac{\alpha-4r}{\alpha}} + c_4 \left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^1(\Omega)}^{\frac{2(\alpha-2r)}{\alpha}}.
 \end{split}
\end{equation}
  Moreover, by the H\"{o}lder inequality,
 \begin{equation}\label{4.12*}
 	\left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^1(\Omega)} \leq \|v_0\|_{L^{\infty}(\Omega)}^{\frac{\alpha}{2}} \cdot N_{k-1}(T).
 \end{equation}
  Hence it follows from \eqref{4.10*}--\eqref{4.12*} that
 \begin{align}
 		c_3 p_k^2 \int_{\Omega} u^{p_k} v^{\alpha-2r}
 		&\leq c_3 c_4 p_k^2 N_{k-1}^{\frac{4r}{\alpha}}(T) \cdot \left\| \nabla\left(u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}}\right) \right\|_{L^2(\Omega)} \cdot \left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^1(\Omega)}^{\frac{\alpha-4r}{\alpha}} \nonumber\\
 		&\quad + c_3 c_4 p_k^2 N_{k-1}^{\frac{4r}{\alpha}}(T) \cdot \left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^1(\Omega)}^{\frac{2(\alpha-2r)}{\alpha}}\nonumber\\
 	&= \left\{ \frac{c_1}{4}\int_{\Omega}\left|\nabla\left(u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}}\right)\right|^2 \right\}^{\frac{1}{2}} \cdot \left(\frac{4}{c_1}\right)^{\frac{1}{2}} c_3 c_4 p_k^2 N_{k-1}^{\frac{4r}{\alpha}}(T) \cdot \left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^1(\Omega)}^{\frac{\alpha-4r}{\alpha}}\nonumber \\
 	&\quad + c_3 c_4 p_k^2 N_{k-1}^{\frac{4r}{\alpha}}(T)  \cdot \left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^1(\Omega)}^{\frac{2(\alpha-2r)}{\alpha}}\\
 	&\leq \frac{c_1}{4}\int_{\Omega}\left|\nabla\left(u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}}\right)\right|^2 + \left(\frac{4}{c_1}(c_3 c_4)^{2}\right) p_k^{4} N_{k-1}^{\frac{8r}{\alpha}}(T)  \cdot \left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^1(\Omega)}^{\frac{2\alpha-8r}{\alpha}}\nonumber\\
 	&\quad + c_3 c_4 p_k^2 N_{k-1}^{\frac{4r}{\alpha}}(T)  \cdot \left\| u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}} \right\|_{L^1(\Omega)}^{\frac{2(\alpha-2r)}{\alpha}}\nonumber\\
 	&\leq  \frac{c_1}{4}\int_{\Omega}\left|\nabla\left(u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}}\right)\right|^2 + c_5 p_k^{4} N_{k-1}^{2}(T)  \cdot \Big\{ \|v_0\|_{L^{\infty}(\Omega)}^{\alpha-4r} + \|v_0\|_{L^{\infty}(\Omega)}^{\alpha-2r} \Big\}\nonumber \\
 	&\leq \frac{c_1}{4}\int_{\Omega}\left|\nabla\left(u^{\frac{p_k}{2}}v^{\frac{\alpha}{2}}\right)\right|^2 + c_6p_k^{4} N_{k-1}^{2}(T),\nonumber
 \end{align}
 where $c_5,c_6>0$ are independent of $k$ and $T$.
	It follows from \eqref{3.37} that
	\begin{align*}
		\frac{d}{dt}\int_\Omega u^{p_k}+b\int_\Omega u^{p_k}&\leq c_{6}p_k^4N_{k-1}^{2}+p_k(a+b)\int_\Omega u^{p_k}-bp_k\int_{\Omega}u^{p_k+1}\\

		&\leq c_{7}p_k^{4} N_{k-1}^{2}+p_k\int_{\{u\geq\frac{a+b}{b}\}} u^{p_k}(a+b-bu)+p_k\int_{\{u\leq\frac{a+b}{b}\}}u^{p_k}(a+b-bu)\\
		&\leq c_{7}p_k^{4} N_{k-1}^{2}+p_k(a+b)\int_{\{u\leq\frac{a+b}{b}\}}u^{p_k}\\
		&\leq c_{7}p_k^{4} N_{k-1}^{2}(T)+p_k|\Omega|(a+b)\bigg(\frac{a+b}{b}\bigg)^{p_k}.
	\end{align*}
Hence, integrating this differential inequality over $(0,t)$ yields
	\begin{align}
		\int_\Omega u^{p_k}(\cdot,t)\leq \int_\Omega u_0^{p_k}+ \frac{c_{7}}{b}p_k^{4} N_{k-1}^{2}(T)+p_k|\Omega|\bigg(\frac{a+b}{b}\bigg)^{p_k+1}.
	\end{align}
	Utilizing the definition of $N_k(T)$ provided in  \eqref{3.36}, we obtain that
	\begin{align}
			N_k(T)&\leq1+\int_\Omega u_0^{p_k}+p_k|\Omega|\bigg(\frac{a+b}{b}\bigg)^{p_k+1}+ c_{8}p_k^{4} N_{k-1}^{2}(T)\nonumber\\
			&\leq p_k+p_k|\Omega|\|u_0\|_{L^\infty(\Omega)}^{p_k}+p_k|\Omega|\bigg(\frac{a+b}{b}\bigg)^{p_k+1}+ c_{8}p_k^{4} N_{k-1}^{2}(T)


	\end{align}
with $c_8:=(\frac{c_7}{b}+1)$ independent of $k,T$. It is observed that
	$$1+|\Omega|\|u_0\|_{L^\infty(\Omega)}^{p_k}+|\Omega|\bigg(\frac{a+b}{b}\bigg)^{p_k+1} \leq \tau^{p_k}$$
	with
$$\tau:=1+(|\Omega|+1)\|u_0\|_{L^\infty(\Omega)}+(|\Omega|+1)\bigg(\frac{a+b}{b}\bigg)^2,$$
and
	\begin{align*}
		c_{8}p_k^{4}&=c_{8}2^{4k}
		=e^{\ln c_{8}+4k\ln 2}
		\leq e^{(\ln c_{8}+4\ln2)k}
		=\big\{e^{(\ln c_{8}+4\ln2)}\big\}^k
	\end{align*}
with $\rho:=\max\{2,e^{(\ln c_{8}+4\ln2)}\}$,
this entails that
\begin{equation*}
		N_k(T)\leq\rho^k\tau^{p_{k}}+\rho^k N_{k-1}^{2}(T).
\end{equation*}

Applying Lemma \ref{lemma3.9} with $q=0$ yields
$$
\|u(\cdot,t)\|_{L^\infty(\Omega)}
\le \liminf_{k\to\infty} N_k^{1/2^k}(T)
\le 2\sqrt{2}\rho^3\tau N_0(T)
\quad\text{for all }0<t\le T.
$$
Since $T>0$ is arbitrary, letting $T\to\infty$ yields the desired uniform bound of $u$ for all $t>0$ and hence the proof is  complete.

According to Lemma \ref{le3.8Moser}, there exists constant $c_1>0$ such that
	\begin{equation*}
		\| u(\cdot,t)\|_{L^{\infty}(\Omega)}\leq c_1~~\mbox{for all}~~t>0.
	\end{equation*}
	Subsequently, by smoothing estimates for the Neumann heat semigroup (see Lemma \ref{le2.5}), we obtain
	\begin{equation}\label{3.31}\|\nabla v(\cdot,t)\|_{L^\infty(\Omega)}\leq c_2~~\mbox{for all}~~t>0.\end{equation} This completes the proof of Theorem \ref{theorem1.1}.

